function lcs_length(left, right)
{
    let previous = replicate([0], right.len() + 1)
    let current = replicate([0], right.len() + 1)

    for (let i in 1 to (left.len() + 1)) {
        current[0] = 0
        let diagonal = 0
        let preceding = 0
        for (let j in 1 to (right.len() + 1)) {
            let above = previous[j]
            if (left[i - 1] == right[j - 1]) {
                preceding = diagonal + 1
            } elif (above > preceding) {
                preceding = above
            }
            current[j] = preceding
            diagonal = above
        }
        let temporary = previous
        previous = current
        current = temporary
    }
    return previous[right.len()] + 0
}

