function solve_from(grid, start)
{
    let index = start
    while (index < 81) {
        if (grid[index] == 0) {
            let row = (index / 9) * 9
            let column = index % 9
            let box = (index / 27) * 27 + (column / 3) * 3
            for (let digit in 1 to 10) {
                let valid = true
                for (let k in 0 to 9) {
                    if (grid[row + k] == digit or grid[column + k * 9] == digit) {
                        valid = false
                        break
                    }
                    if (grid[box + (k / 3) * 9 + k % 3] == digit) {
                        valid = false
                        break
                    }
                }
                if (valid) {
                    grid[index] = digit
                    if (this(grid, index + 1)) {
                        return true
                    }
                }
            }
            grid[index] = 0
            return false
        }
        index = index + 1
    }
    return true
}

function solve_board(grid)
{
    return solve_from(grid, 0)
}

