function distance_less(a, b)
{
    return a[0] < b[0]
}

function dijkstra(graph, source, size)
{
    let dist = replicate([1000000000000], size)
    dist[source] = 0
    let queue = [[0, source]]
    while (len(queue) > 0) {
        let current = heap::pop(queue, distance_less)
        let distance = current[0]
        let vertex = current[1]
        if (distance == dist[vertex] and vertex in graph) {
            for (let edge in graph[vertex]) {
                let target = edge[0]
                let alt = distance + edge[1]
                if (alt < dist[target]) {
                    dist[target] = alt
                    heap::push(queue, [alt, target], distance_less)
                }
            }
        }
    }
    return copy(dist)
}

