var pi = 3.141592653589793
var solar_mass = 4.0 * pi * pi
var days_per_year = 365.24

let Body = types::make_type(
    'x' : types::Float,
    'y' : types::Float,
    'z' : types::Float,
    'vx' : types::Float,
    'vy' : types::Float,
    'vz' : types::Float,
    'mass' : types::Float,
)

function advance(bodies, dt)
{
    let count = len(bodies)
    for (let i in 0 to count) {
        let bi = bodies[i]
        for (let j in i + 1 to count) {
            let bj = bodies[j]
            let dx = bi::x - bj::x
            let dy = bi::y - bj::y
            let dz = bi::z - bj::z
            let d2 = dx * dx + dy * dy + dz * dz
            let mag = dt / (d2 * math::sqrt(d2))
            let mi = bi::mass * mag
            let mj = bj::mass * mag
            bi['vx'] = bi::vx - dx * mj
            bi['vy'] = bi::vy - dy * mj
            bi['vz'] = bi::vz - dz * mj
            bj['vx'] = bj::vx + dx * mi
            bj['vy'] = bj::vy + dy * mi
            bj['vz'] = bj::vz + dz * mi
        }
    }
    for (let i in 0 to count) {
        let b = bodies[i]
        b['x'] = b::x + dt * b::vx
        b['y'] = b::y + dt * b::vy
        b['z'] = b::z + dt * b::vz
    }
}

function energy(bodies)
{
    var e = 0.0
    let count = len(bodies)
    for (let i in 0 to count) {
        let bi = bodies[i]
        e = e + 0.5 * bi::mass * (bi::vx * bi::vx + bi::vy * bi::vy + bi::vz * bi::vz)
        for (let j in i + 1 to count) {
            let bj = bodies[j]
            let dx = bi::x - bj::x
            let dy = bi::y - bj::y
            let dz = bi::z - bj::z
            e = e - bi::mass * bj::mass / math::sqrt(dx * dx + dy * dy + dz * dz)
        }
    }
    return e + 0.0
}

function offset_momentum(bodies)
{
    var px = 0.0
    var py = 0.0
    var pz = 0.0
    for (let b in bodies) {
        px = px + b::vx * b::mass
        py = py + b::vy * b::mass
        pz = pz + b::vz * b::mass
    }
    let sun = bodies[0]
    sun['vx'] = (0.0 - px) / solar_mass
    sun['vy'] = (0.0 - py) / solar_mass
    sun['vz'] = (0.0 - pz) / solar_mass
}

